namespace { constexpr std::array<std::string_view, 17> docs = {
    "\\brief Enumeration of the playback device notifications",
    "Playback device has been started",
    "Playback device has been stopped",
    "Playback device has been rerouted (Generated on platforms that support automatic stream routing)",
    "Playback device interruption has begun (Generated on Apple mobile platforms)",
    "Playback device interruption has ended (Generated on Apple mobile platforms)",
    "Playback device has been unlocked (Generated by Emscripten/WebAudio)",
    "\\brief Callable that is called to notify of changes to the playback device state",
    "\\brief Get a list of the names of all available audio playback devices\n\nThis function returns a vector of strings containing\nthe names of all available audio playback devices.\n\nIf the operating system reports multiple devices with\nthe same name, a number will be appended to the name\nof all subsequent devices to distinguish them from each\nother. This guarantees that every entry returned by this\nfunction will represent a unique device.\n\nFor example, if the operating system reports multiple\ndevices with the name \"Sound Card\", the entries returned\nwould be:\n- Sound Card\n- Sound Card 2\n- Sound Card 3\n- ...\n\nThe default device, if one is marked as such, will be\nplaced at the beginning of the vector.\n\nIf no devices are available, this function will return\nan empty vector.\n\n\\return A vector of strings containing the device names or an empty vector if no devices are available",
    "\\brief Get the name of the default audio playback device\n\nThis function returns the name of the default audio\nplayback device. If none is available, `std::nullopt`\nis returned.\n\nNote that depending on when this function is called, the\ndefault device reported by the operating system might\nchange e.g. when a USB audio device is plugged into or\nunplugged from the system.\n\n\\return The name of the default audio playback device",
    "\\brief Set the audio playback device\n\nThis function sets the audio playback device to the device\nwith the given `name`. It can be called on the fly (i.e:\nwhile sounds are playing).\n\nIf there are sounds playing when the audio playback\ndevice is switched, the sounds will continue playing\nuninterrupted on the new audio playback device.\n\n\\param name The name of the audio playback device\n\n\\return `true`, if it was able to set the requested device\n\n\\see `getAvailableDevices`, `getDefaultDevice`, `setDeviceToDefault`, `setDeviceToNull`",
    "\\brief Set the audio playback device to the default\n\nThis function sets the audio playback device to the\ndefault device. It can be called on the fly (i.e:\nwhile sounds are playing).\n\nIf there are sounds playing when the audio playback\ndevice is switched, the sounds will continue playing\nuninterrupted on the new audio playback device.\n\nWhen certain backends are used, using the default device\nwill enable automatic stream routing. When automatic\nstream routing is enabled, audio data is automatically\nsent to whichever physical audio device is currently\nmarked as the default on the system. If the default device\nchanges due to e.g. a device being added to or removed\nfrom the system or the user marking another device as the\ndefault, automatic stream routing will seamlessly reroute\nthe audio data to the new default device without any\nmanual intervention.\n\nAutomatic stream routing is currently supported when using\nthe WASAPI or DirectSound backend on Windows or the\nCore Audio backend on macOS and iOS.\n\nDepending on the order in which hardware devices are\ninitialized e.g. after resuming from sleep, the default\ndevice might change one or more times in rapid succession\nbefore it reverts back to the state in which it was\nbefore the system went to sleep.\n\n\\return `true`, if it was able to set the audio playback device to the default device\n\n\\see `getAvailableDevices`, `getDefaultDevice`, `setDevice`, `setDeviceToNull`",
    "\\brief Set the audio playback device to the null device\n\nThis function sets the audio playback device to the\nnull device. It can be called on the fly (i.e:\nwhile sounds are playing).\n\nIf there are sounds playing when the audio playback\ndevice is switched, the sounds will continue playing\nuninterrupted on the new audio playback device.\n\nAudio data routed to the null device will be discarded\nby the backend. This can be used to keep sounds playing\nwithout having them actually output on a physical\naudio playback device.\n\n\\return `true`, if it was able to set the audio playback device to the null device\n\n\\see `getAvailableDevices`, `getDefaultDevice`, `setDevice`, `setDeviceToDefault`",
    "\\brief Get the name of the current audio playback device\n\n\\return The name of the current audio playback device or `std::nullopt` if there is none",
    "\\brief Get the sample rate of the current audio playback device\n\n\\return The sample rate of the current audio playback device or `std::nullopt` if there is none",
    "\\brief Check if the current playback device is the default device\n\nThis function will return `false` if there is no\ncurrent playback device.\n\n\\return `true`, if the current playback device is the default device",
    "\\brief Set a callback that should be called to notify of changes to the playback device state\n\nWarning: Do not attempt to alter the device state from\nwithin this callback. This includes changing the device\nand even creating/destroying sound objects since that\ncould indirectly cause the playback device to be\ncreated/destroyed. Also do not attempt to set the\nnotification callback from within this callback. Doing\nso will result in a deadlock.\n\nWhen receiving a notification via this callback, store\nthe information somewhere and react on it from another\nthread e.g. the main thread within the application.\n\n\\param callback The callback that should be called to notify of changes to the playback device state",
}; }

void bind_PlaybackDevice(lua_glue::StateView lua) {
    lua_glue::Table sf = lua_sf::sf_table(lua);
    lua_glue::Table sf_PlaybackDevice = sf["PlaybackDevice"].get_or_create<lua_glue::Table>();
    LUASF_STUB_DOC(docs[0]);
    LUASF_STUB_CLASS("sf.PlaybackDevice.Notification");
    LUASF_STUB_DOC(docs[1]);
    LUASF_STUB_FIELD("DeviceStarted", "sf.PlaybackDevice.Notification");
    LUASF_STUB_DOC(docs[2]);
    LUASF_STUB_FIELD("DeviceStopped", "sf.PlaybackDevice.Notification");
    LUASF_STUB_DOC(docs[3]);
    LUASF_STUB_FIELD("DeviceRerouted", "sf.PlaybackDevice.Notification");
    LUASF_STUB_DOC(docs[4]);
    LUASF_STUB_FIELD("DeviceInterruptionBegan", "sf.PlaybackDevice.Notification");
    LUASF_STUB_DOC(docs[5]);
    LUASF_STUB_FIELD("DeviceInterruptionEnded", "sf.PlaybackDevice.Notification");
    LUASF_STUB_DOC(docs[6]);
    LUASF_STUB_FIELD("DeviceUnlocked", "sf.PlaybackDevice.Notification");
    lua_glue::BindEnum<sf::PlaybackDevice::Notification>(sf_PlaybackDevice, "Notification", {
        {"DeviceStarted", sf::PlaybackDevice::Notification::DeviceStarted},
        {"DeviceStopped", sf::PlaybackDevice::Notification::DeviceStopped},
        {"DeviceRerouted", sf::PlaybackDevice::Notification::DeviceRerouted},
        {"DeviceInterruptionBegan", sf::PlaybackDevice::Notification::DeviceInterruptionBegan},
        {"DeviceInterruptionEnded", sf::PlaybackDevice::Notification::DeviceInterruptionEnded},
        {"DeviceUnlocked", sf::PlaybackDevice::Notification::DeviceUnlocked}
    });
    LUASF_STUB_DOC(docs[7]);
    LUASF_STUB_ALIAS("sf.PlaybackDevice.NotificationCallback", "fun(notification: sf.PlaybackDevice.Notification)");
    LUASF_STUB_DOC(docs[8]);
    LUASF_STUB_FUNCTION("sf.PlaybackDevice", "getAvailableDevices", "fun(): string[]");
    lua_glue::BindCallable(sf_PlaybackDevice, "getAvailableDevices",
        [lua]() -> lua_glue::Object {
            return lua_sf::vector_to_object(lua, sf::PlaybackDevice::getAvailableDevices());
        },
        docs[8]
    );
    LUASF_STUB_DOC(docs[9]);
    LUASF_STUB_FUNCTION("sf.PlaybackDevice", "getDefaultDevice", "fun(): string|nil");
    lua_glue::BindCallable(sf_PlaybackDevice, "getDefaultDevice",
        [lua]() -> lua_glue::Object {
            return lua_sf::optional_to_object(lua, sf::PlaybackDevice::getDefaultDevice());
        },
        docs[9]
    );
    LUASF_STUB_DOC(docs[10]);
    LUASF_STUB_FUNCTION("sf.PlaybackDevice", "setDevice", "fun(name: string): boolean");
    lua_glue::BindCallable(sf_PlaybackDevice, "setDevice",
        [](std::string name) -> bool {
            return sf::PlaybackDevice::setDevice(name);
        },
        docs[10]
    );
    LUASF_STUB_DOC(docs[11]);
    LUASF_STUB_FUNCTION("sf.PlaybackDevice", "setDeviceToDefault", "fun(): boolean");
    lua_glue::BindCallable(sf_PlaybackDevice, "setDeviceToDefault",
        []() -> bool {
            return sf::PlaybackDevice::setDeviceToDefault();
        },
        docs[11]
    );
    LUASF_STUB_DOC(docs[12]);
    LUASF_STUB_FUNCTION("sf.PlaybackDevice", "setDeviceToNull", "fun(): boolean");
    lua_glue::BindCallable(sf_PlaybackDevice, "setDeviceToNull",
        []() -> bool {
            return sf::PlaybackDevice::setDeviceToNull();
        },
        docs[12]
    );
    LUASF_STUB_DOC(docs[13]);
    LUASF_STUB_FUNCTION("sf.PlaybackDevice", "getDevice", "fun(): string|nil");
    lua_glue::BindCallable(sf_PlaybackDevice, "getDevice",
        [lua]() -> lua_glue::Object {
            return lua_sf::optional_to_object(lua, sf::PlaybackDevice::getDevice());
        },
        docs[13]
    );
    LUASF_STUB_DOC(docs[14]);
    LUASF_STUB_FUNCTION("sf.PlaybackDevice", "getDeviceSampleRate", "fun(): integer|nil");
    lua_glue::BindCallable(sf_PlaybackDevice, "getDeviceSampleRate",
        [lua]() -> lua_glue::Object {
            return lua_sf::optional_to_object(lua, sf::PlaybackDevice::getDeviceSampleRate());
        },
        docs[14]
    );
    LUASF_STUB_DOC(docs[15]);
    LUASF_STUB_FUNCTION("sf.PlaybackDevice", "isDefaultDevice", "fun(): boolean");
    lua_glue::BindCallable(sf_PlaybackDevice, "isDefaultDevice",
        []() -> bool {
            return sf::PlaybackDevice::isDefaultDevice();
        },
        docs[15]
    );
    LUASF_STUB_DOC(docs[16]);
    LUASF_STUB_FUNCTION("sf.PlaybackDevice", "setNotificationCallback", "fun(callback: sf.PlaybackDevice.NotificationCallback|nil)");
    lua_glue::BindCallable(sf_PlaybackDevice, "setNotificationCallback",
        [](lua_glue::Object callback) {
            static const unsigned char callbackOwner{};
            lua_State *state = callback.lua_state();
            if (lua_sf::is_nil_object(callback)) {
                sf::PlaybackDevice::setNotificationCallback({});
                lua_sf::detail::unregisterStateQuiesceCallback(state, &callbackOwner);
                return;
            }
            auto nativeCallback = lua_sf::callback::from_object<sf::PlaybackDevice::NotificationCallback, lua_sf::callback::NativeThreadBoundaryCodec>(callback, lua_sf::callback::CallbackOptions{"sf::PlaybackDevice::setNotificationCallback.callback", true});
            lua_sf::detail::registerStateQuiesceCallback(
                state, &callbackOwner,
                []() noexcept { sf::PlaybackDevice::setNotificationCallback({}); });
            sf::PlaybackDevice::setNotificationCallback(std::move(nativeCallback));
        },
        docs[16]
    );
}
